//! Reads and writes the layout declarations that users can edit in Rex's generated files.

use std::borrow::Cow;
use std::fmt::Write as _;
use std::path::Path;

pub(super) const GENERATED: &str = "-- Generated by milo setup.\n";
pub(super) const DEFAULT_USAGE_ROWS: u32 = 2;

const START_LISTENER: &str = "\n-- During a syntax check or a one-off layout, do not start a listener.\n\
    if arrange_new_tabs and not rex.args and not os.getenv(\"MILO_CHECKING_REX\") then\n  \
    rex.exec.start({ milo, \"listen\" }, { detach = true })\nend\n";
const OLD_START_LISTENER: &str = "\n-- During a syntax check or a one-off layout, do not start a listener.\n\
    if not rex.args and not os.getenv(\"MILO_CHECKING_REX\") then\n  \
    rex.exec.start({ milo, \"listen\" }, { detach = true })\nend\n";

const LISTENER_COMMENT: &str = "-- During a syntax check or a one-off layout, do not start a listener.";
const LISTENER_GUARD: &str = "if not rex.args and not os.getenv(\"MILO_CHECKING_REX\") then";
const CHOSEN_LISTENER_GUARD: &str =
    "if arrange_new_tabs and not rex.args and not os.getenv(\"MILO_CHECKING_REX\") then";
const LISTENER_CALL: &str = "  rex.exec.start({ milo, \"listen\" }, { detach = true, env = { XDG_CONFIG_HOME = ";
const LISTENER_STATE_ARG: &str = ", XDG_STATE_HOME = ";
const LISTENER_CALL_END: &str = " } })";

#[derive(Clone, Copy)]
pub(super) struct ListenerEnv<'a> {
    pub config_home: &'a Path,
    pub state_home: &'a Path,
}
const ACTIONS: &str = include_str!("actions.lua");
const LISTENER: &str = include_str!("listener.lua");
// Older binaries shipped a ten-row default; later templates must not
// mistake a hand-edited ten-row setting for that old default.
const TEN_ROW_ACTIONS: [u64; 4] =
    [0x97cf_a17d_8775_e350, 0x560c_5b9a_caa8_625d, 0x2438_eceb_d658_d06f, 0x1d1f_8dd4_6b14_c588];
const TWO_ROW_ACTIONS: [u64; 3] = [0x5b89_2e57_9222_edf1, 0xe209_f094_9daa_1761, 0x87e4_ca78_9f5c_8cc4];

pub(super) fn probe_lua(layout: &Layout, executable: &Path) -> String {
    let mut lua = actions_prefix(layout, &lua_path(executable));
    writeln!(lua, "local trial_profile = {}", lua_string(layout.rail_code().as_bytes())).expect("writing to a string");
    lua.push_str(ACTIONS);
    lua
}

/// Match whole shipped templates, including the last one, without keeping a
/// second copy of the old Lua or treating any custom code as ours.
fn fingerprint(text: &str) -> u64 {
    text.bytes().fold(0xcbf2_9ce4_8422_2325, |hash, byte| (hash ^ u64::from(byte)).wrapping_mul(0x0100_0000_01b3))
}

struct Declarations<'a> {
    values: [&'a str; 4],
    panes: [Option<&'a str>; 3],
    insert_panes: usize,
    executable: Option<&'a str>,
}

impl Declarations<'_> {
    fn layout(&self) -> Option<Layout> {
        let [width, outline_share, rows, new_tabs] = self.values;
        for text in [width, outline_share] {
            let number = text.parse::<f64>().ok()?;
            if !(0.0 < number && number < 1.0) {
                return None;
            }
        }
        rows.parse::<u32>().ok().filter(|&rows| rows > 0)?;
        let mut panes = [false; 3];
        for (pane, value) in panes.iter_mut().zip(self.panes) {
            if let Some(value) = value {
                *pane = value.parse().ok()?;
            }
        }
        Some(Layout {
            width: width.into(),
            outline_share: outline_share.into(),
            usage_rows: rows.into(),
            new_tabs: new_tabs.parse().ok()?,
            geometry: Geometry::default(),
            panes,
        })
    }
}
/// Named panes keep Lua and the on-screen choices in the same order.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum TabPane {
    Outline,
    History,
    Usage,
}

impl TabPane {
    pub const ALL: [Self; 3] = [Self::Outline, Self::History, Self::Usage];

    pub const fn name(self) -> &'static str {
        match self {
            Self::Outline => "outline",
            Self::History => "history",
            Self::Usage => "usage",
        }
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(super) enum Side {
    #[default]
    Left,
    Right,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) struct Geometry {
    pub side: Side,
    pub order: [TabPane; 3],
    /// Per role, in millionths of the entire rail height.
    pub shares: Option<[u32; 3]>,
}

impl Default for Geometry {
    fn default() -> Self {
        Self { side: Side::Left, order: TabPane::ALL, shares: None }
    }
}

/// A width preset pairs its display name and exact Lua proportion.
#[derive(Clone, Copy)]
pub(super) struct Width {
    name: &'static str,
    pub proportion: &'static str,
}

pub(super) const WIDTHS: [Width; 3] = [
    Width { name: "Thin", proportion: "0.20" },
    Width { name: "Medium", proportion: "0.30" },
    Width { name: "Wide", proportion: "0.38" },
];

/// Display names are fixed; a proportion set by hand is kept until the user changes it here.
#[derive(Clone, PartialEq, Eq)]
pub(super) struct Layout {
    pub panes: [bool; 3],
    pub new_tabs: bool,
    pub width: String,
    pub outline_share: String,
    pub usage_rows: String,
    pub geometry: Geometry,
}

impl Default for Layout {
    fn default() -> Self {
        Self {
            panes: [true; 3],
            new_tabs: false,
            width: WIDTHS[0].proportion.into(),
            outline_share: "0.70".into(),
            usage_rows: DEFAULT_USAGE_ROWS.to_string(),
            geometry: Geometry::default(),
        }
    }
}

impl Layout {
    /// Only these choices can affect either the current tab or a future one.
    pub fn enabled(&self) -> bool {
        self.new_tabs || self.panes.contains(&true)
    }

    pub fn chosen(&self, pane: TabPane) -> bool {
        self.panes[pane as usize]
    }

    pub fn toggle(&mut self, pane: TabPane) {
        self.panes[pane as usize] = !self.chosen(pane);
    }

    /// Only exact presets get a preset label, even if a hand edit is close.
    pub fn width_name(&self) -> &'static str {
        self.preset().map_or("Custom", |width| width.name)
    }

    fn preset(&self) -> Option<Width> {
        WIDTHS.into_iter().find(|width| width.proportion == self.width)
    }

    /// Pressing change after a custom width starts the normal cycle again.
    pub fn next_width(&mut self) {
        let next = WIDTHS.iter().skip_while(|width| width.proportion != self.width).nth(1).unwrap_or(&WIDTHS[0]);
        self.width.clear();
        self.width.push_str(next.proportion);
    }

    /// No Rex IDs or executable data belong in a remembered rail.
    pub(super) fn rail_code(&self) -> String {
        let mut code = format!(
            "v1 {} {} {} {} ",
            if self.geometry.side == Side::Left { "l" } else { "r" },
            self.width,
            self.outline_share,
            self.usage_rows,
        );
        for pane in self.geometry.order {
            code.push(match pane {
                TabPane::Outline => 'o',
                TabPane::History => 'h',
                TabPane::Usage => 'u',
            });
        }
        code.push(' ');
        for enabled in self.panes {
            code.push(if enabled { '1' } else { '0' });
        }
        if let Some([outline, history, usage]) = self.geometry.shares {
            write!(code, " {outline} {history} {usage}").expect("writing to a string");
        }
        code
    }

    pub(super) fn parse_rail(code: &str) -> Option<Self> {
        let mut fields = code.split_ascii_whitespace();
        if fields.next()? != "v1" {
            return None;
        }
        let side = match fields.next()? {
            "l" => Side::Left,
            "r" => Side::Right,
            _ => return None,
        };
        let width = ratio(fields.next()?)?.into();
        let outline_share = ratio(fields.next()?)?.into();
        let usage_rows = fields.next()?;
        if usage_rows.parse::<u32>().ok()? == 0 {
            return None;
        }
        let mut order = TabPane::ALL;
        let mut seen = [false; 3];
        let [a, b, c] = *fields.next()?.as_bytes() else { return None };
        for (pane, letter) in order.iter_mut().zip([a, b, c]) {
            *pane = match letter {
                b'o' => TabPane::Outline,
                b'h' => TabPane::History,
                b'u' => TabPane::Usage,
                _ => return None,
            };
            if std::mem::replace(&mut seen[*pane as usize], true) {
                return None;
            }
        }
        let mut panes = [false; 3];
        let [a, b, c] = *fields.next()?.as_bytes() else { return None };
        for (enabled, byte) in panes.iter_mut().zip([a, b, c]) {
            *enabled = match byte {
                b'0' => false,
                b'1' => true,
                _ => return None,
            };
        }
        let shares = if let Some(outline) = fields.next() {
            let shares = [
                outline.parse::<u32>().ok()?,
                fields.next()?.parse::<u32>().ok()?,
                fields.next()?.parse::<u32>().ok()?,
            ];
            if shares.iter().any(|&share| share > 1_000_000) || shares == [0; 3] {
                return None;
            }
            Some(shares)
        } else {
            None
        };
        fields.next().is_none().then(|| Self {
            width,
            outline_share,
            usage_rows: usage_rows.into(),
            panes,
            new_tabs: false,
            geometry: Geometry { side, order, shares },
        })
    }

    /// Read the layout values without rewriting the rest of the user's Lua.
    pub(super) fn parse(text: &str) -> Option<Self> {
        let fields = declarations(text)?;
        let mut layout = fields.layout()?;
        // A legacy generated default is not a saved resize. Keep custom Lua,
        // other row values, and profiles (parsed separately) exactly as chosen.
        if layout.usage_rows == "10"
            && let Some(exe) = fields.executable
            && shipped_action_body(text, &layout, exe)
                .is_some_and(|body| body != ACTIONS && TEN_ROW_ACTIONS.contains(&fingerprint(body)))
        {
            layout.usage_rows = DEFAULT_USAGE_ROWS.to_string();
        }
        Some(layout)
    }
}

fn ratio(value: &str) -> Option<&str> {
    let number = value.parse::<f64>().ok()?;
    (0.0 < number && number < 1.0).then_some(value)
}

fn declarations(text: &str) -> Option<Declarations<'_>> {
    let mut lines = text.lines();
    if lines.next()?.trim_end() != GENERATED.trim_end() {
        return None;
    }
    let mut comment = None;
    let mut lines = lines.map(move |line| lua_code(line, &mut comment)).filter(|line| *line != Some(""));
    let mut values = [None; 4];
    let mut insert_panes = None;
    for line in lines.by_ref() {
        let line = line?;
        let (key, value) = line.split_once('=')?;
        let value = value.trim();
        let field = match key.trim_end() {
            "local column_width" => 0,
            "local outline_share" => 1,
            "local usage_rows" => 2,
            "local arrange_new_tabs" => 3,
            "local chosen" if value == "{" => {
                insert_panes = Some(value.as_ptr().addr() - text.as_ptr().addr() + 1);
                break;
            }
            _ => return None,
        };
        if values[field].replace(value).is_some() {
            return None;
        }
    }
    let [Some(width), Some(outline), Some(rows), Some(new_tabs)] = values else { return None };
    let insert_panes = insert_panes?;
    let mut panes = [None; 3];
    for line in lines.by_ref() {
        let line = line?;
        if line == "}" {
            let tail = &text[line.as_ptr().addr() - text.as_ptr().addr() + 1..];
            let executable = tail.strip_prefix("\n\nlocal milo = ").and_then(|tail| {
                let (literal, _) = tail.split_once('\n')?;
                (lua_string_end(literal) == Some(literal.len())).then_some(literal)
            });
            return Some(Declarations { values: [width, outline, rows, new_tabs], panes, insert_panes, executable });
        }
        let (key, value) = line.split_once('=')?;
        let pane = TabPane::ALL.into_iter().find(|pane| pane.name() == key.trim_end())?;
        let value = value.trim().trim_end_matches([',', ';']).trim_end();
        if panes[pane as usize].replace(value).is_some() {
            return None;
        }
    }
    None
}

/// Take a single declaration, not a second statement hiding after a comment.
fn lua_code<'a>(mut line: &'a str, comment: &mut Option<usize>) -> Option<&'a str> {
    if let Some(depth) = *comment {
        let Some(tail) = comment_tail(line, depth) else { return Some("") };
        *comment = None;
        line = tail;
    }
    let mut declaration = "";
    loop {
        let (code, rest) = line.split_once("--").unwrap_or((line, ""));
        let code = code.trim();
        if !code.is_empty() {
            if !declaration.is_empty() {
                return None;
            }
            declaration = code;
        }
        let Some((depth, rest)) = long_bracket(rest, '[') else { return Some(declaration) };
        let Some(tail) = comment_tail(rest, depth) else {
            *comment = Some(depth);
            return Some(declaration);
        };
        line = tail;
    }
}

fn lua_string_end(text: &str) -> Option<usize> {
    let mut escaped = false;
    for (i, byte) in text.strip_prefix('"')?.bytes().enumerate() {
        if escaped {
            escaped = false;
        } else if byte == b'"' {
            return Some(i + 2);
        } else {
            escaped = byte == b'\\';
        }
    }
    None
}

fn comment_tail(line: &str, depth: usize) -> Option<&str> {
    line.match_indices(']').find_map(|(i, _)| {
        let (end, tail) = long_bracket(&line[i..], ']')?;
        (depth == end).then_some(tail)
    })
}

fn long_bracket(text: &str, bracket: char) -> Option<(usize, &str)> {
    let text = text.strip_prefix(bracket)?;
    let rest = text.trim_start_matches('=');
    Some((text.len() - rest.len(), rest.strip_prefix(bracket)?))
}

/// A path in a Lua 5.1 string, even if some of its bytes are not UTF-8.
pub(super) fn lua_path(path: &Path) -> String {
    lua_string(path.as_os_str().as_encoded_bytes())
}

fn lua_string(bytes: &[u8]) -> String {
    let mut literal = String::from("\"");
    for &byte in bytes {
        match byte {
            b'"' | b'\\' => literal.extend(['\\', char::from(byte)]),
            b' '..=b'~' => literal.push(char::from(byte)),
            _ => write!(literal, "\\{byte:03}").expect("writing to a string"),
        }
    }
    literal.push('"');
    literal
}

/// Edit just the layout values of a hand-edited file; its action code and comments stay put.
pub(super) fn update_actions(
    text: &str,
    layout: &Layout,
    executable: &Path,
    env: ListenerEnv<'_>,
) -> Option<Option<String>> {
    let fields = declarations(text)?;
    let old = fields.layout()?;
    if fields.executable.is_some_and(|previous| shipped_actions(text, &old, previous)) {
        let generated = rex_lua(layout, executable, env);
        return Some((generated != text).then_some(generated));
    }
    let newline = if text.contains("\r\n") { "\r\n" } else { "\n" };
    let with_newlines = |footer: &'static str| {
        if newline == "\n" { Cow::Borrowed(footer) } else { Cow::Owned(footer.replace('\n', newline)) }
    };
    let legacy =
        [(with_newlines(OLD_START_LISTENER), LISTENER_GUARD), (with_newlines(START_LISTENER), CHOSEN_LISTENER_GUARD)];
    let legacy_suffix =
        legacy.iter().find_map(|(footer, guard)| text.ends_with(footer.as_ref()).then_some((footer.len(), *guard)));
    if old == *layout && legacy_suffix.is_none() {
        return Some(None);
    }

    let mut edits = Vec::new();
    let mut replace = |before: &str, after: &str| {
        if before != after {
            // Each value is a slice of the input.
            let start = before.as_ptr().addr() - text.as_ptr().addr();
            edits.push((start..start + before.len(), after.to_owned()));
        }
    };
    let values = [
        layout.width.as_str(),
        &layout.outline_share,
        &layout.usage_rows,
        if layout.new_tabs { "true" } else { "false" },
    ];
    for (before, after) in fields.values.into_iter().zip(values) {
        replace(before, after);
    }
    let mut added = String::new();
    for (pane, before) in TabPane::ALL.into_iter().zip(fields.panes) {
        let chosen = layout.chosen(pane);
        if let Some(before) = before {
            replace(before, if chosen { "true" } else { "false" });
        } else if chosen {
            // Insert immediately after the opening brace, before any following comment.
            write!(added, "{newline}  {} = true,", pane.name()).expect("writing to a string");
        }
    }
    let start = fields.insert_panes;
    if !added.is_empty() {
        edits.push((start..start, added));
    }
    edits.sort_unstable_by_key(|(range, _)| range.start);
    let mut updated = text.to_owned();
    for (range, value) in edits.into_iter().rev() {
        updated.replace_range(range, &value);
    }
    if old.new_tabs != layout.new_tabs {
        if let Some((len, _)) = legacy_suffix {
            updated.truncate(updated.len() - len);
        } else if let Some(body) = strip_scoped_footer(&updated, newline) {
            updated.truncate(body.len());
        } else if legacy.iter().any(|(footer, _)| updated.contains(footer.as_ref()))
            || updated.lines().any(|line| launcher_state(line).is_some())
        {
            // Do not rewrite a launcher buried in custom code.
            return None;
        }
        if layout.new_tabs {
            push_listener(&mut updated, env, newline, CHOSEN_LISTENER_GUARD);
        }
    } else if let Some((len, guard)) = legacy_suffix {
        updated.truncate(updated.len() - len);
        push_listener(&mut updated, env, newline, guard);
    }
    Some(Some(updated))
}

pub(super) fn owns_actions(text: &str) -> bool {
    declarations(text).is_some_and(|fields| {
        fields.layout().zip(fields.executable).is_some_and(|(layout, exe)| shipped_actions(text, &layout, exe))
    })
}

pub(super) fn launcher_matches(text: &str, executable: &Path) -> Option<bool> {
    declarations(text)?.executable.map(|value| value == lua_path(executable))
}

fn shipped_actions(text: &str, layout: &Layout, exe: &str) -> bool {
    shipped_action_body(text, layout, exe).is_some()
}

fn shipped_action_body<'a>(text: &'a str, layout: &Layout, exe: &str) -> Option<&'a str> {
    let tail = text.strip_prefix(&actions_prefix(layout, exe))?;
    let body = strip_scoped_footer(tail, "\n")
        .or_else(|| tail.strip_suffix(OLD_START_LISTENER))
        .or_else(|| tail.strip_suffix(START_LISTENER))
        .unwrap_or(tail);
    let owns = body == ACTIONS || {
        let hash = fingerprint(body);
        TEN_ROW_ACTIONS.contains(&hash) || TWO_ROW_ACTIONS.contains(&hash)
    };
    owns.then_some(body)
}

/// The installed and temporary layouts must run exactly the same actions.
pub(super) fn rex_lua(layout: &Layout, executable: &Path, env: ListenerEnv<'_>) -> String {
    let mut lua = actions_prefix(layout, &lua_path(executable));
    lua.push_str(ACTIONS);
    if layout.enabled() {
        push_listener(&mut lua, env, "\n", LISTENER_GUARD);
    }
    lua
}

fn push_listener(lua: &mut String, env: ListenerEnv<'_>, nl: &str, guard: &str) {
    let config = lua_path(env.config_home);
    let state = lua_path(env.state_home);
    write!(
        lua,
        "{nl}{LISTENER_COMMENT}{nl}{guard}{nl}{LISTENER_CALL}{config}{LISTENER_STATE_ARG}{state}{LISTENER_CALL_END}{nl}end{nl}",
    )
    .expect("writing to a string");
}

fn launcher_state(call: &str) -> Option<&str> {
    let args = call.strip_prefix(LISTENER_CALL)?.strip_suffix(LISTENER_CALL_END)?;
    let state = args.get(lua_string_end(args)?..)?.strip_prefix(LISTENER_STATE_ARG)?;
    (lua_string_end(state) == Some(state.len())).then_some(state)
}

/// Compare the generated environment without using paths found in the user's Lua.
pub(super) fn listener_state_matches(text: &str, state_home: &Path) -> bool {
    let mut lines = text.lines();
    if lines.next().is_none_or(|line| line.trim_end() != GENERATED.trim_end()) {
        return true;
    }
    let mut launchers = lines.filter_map(launcher_state);
    let Some(first) = launchers.next() else { return true };
    let expected = lua_path(state_home);
    first == expected && launchers.all(|state| state == expected)
}

fn strip_scoped_footer<'a>(text: &'a str, nl: &str) -> Option<&'a str> {
    let (text, call) = text.strip_suffix(nl)?.strip_suffix("end")?.strip_suffix(nl)?.rsplit_once(nl)?;
    launcher_state(call)?;
    let (text, guard) = text.rsplit_once(nl)?;
    let (body, comment) = text.rsplit_once(nl)?;
    (matches!(guard, LISTENER_GUARD | CHOSEN_LISTENER_GUARD) && comment == LISTENER_COMMENT).then_some(body)
}

fn actions_prefix(layout: &Layout, executable: &str) -> String {
    let mut lua = format!(
        "{GENERATED}\n-- Fraction of the tab for the left column.\nlocal column_width = {}\n\
         -- Fraction of that column for the outline when history is below it.\nlocal outline_share = {}\n\
         -- Terminal rows for the usage strip.\nlocal usage_rows = {}\n\
         -- Whether Rex arranges each new shell tab.\nlocal arrange_new_tabs = {}\n\n\
         -- The panes included by Milo: Arrange This Tab.\nlocal chosen = {{\n",
        layout.width, layout.outline_share, layout.usage_rows, layout.new_tabs,
    );
    for pane in TabPane::ALL {
        if layout.chosen(pane) {
            writeln!(lua, "  {} = true,", pane.name()).expect("writing to a string");
        }
    }
    lua.push_str("}\n\n");
    writeln!(lua, "local milo = {executable}\n").expect("writing to a string");
    lua
}

/// The listener reuses the installed actions rather than embedding another copy.
pub(super) fn listener_lua(rex_file: &Path) -> String {
    format!("{}{LISTENER}", listener_prefix(rex_file))
}

fn listener_prefix(rex_file: &Path) -> String {
    format!(
        "{GENERATED}-- Used by milo listen to arrange newly opened shell tabs.\nlocal rex_config = {}\n\n",
        lua_path(rex_file),
    )
}

pub(super) fn owns_listener(text: &str, rex_file: &Path) -> bool {
    text.strip_prefix(&listener_prefix(rex_file)).is_some_and(|body| {
        body == LISTENER
            || [
                0x9a38_08cb_8bb7_54d8, 0x18ff_d6b9_f7bd_6f63, 0x3af5_6341_9c89_8eb8, 0x6814_92ce_bca8_054a,
                0x1ed2_af59_4c5b_4bf4, 0x7b13_2b45_6752_1e02, 0x9a88_3230_71bd_27e5,
            ]
            .contains(&fingerprint(body))
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    const CONFIG_HOME: &str = "/fixture/config home";
    const STATE_HOME: &str = "/fixture/state'home";

    fn environment() -> ListenerEnv<'static> {
        ListenerEnv { config_home: Path::new(CONFIG_HOME), state_home: Path::new(STATE_HOME) }
    }

    #[test]
    fn shipped_launcher_pins_the_install_paths_and_detects_state_mismatch() {
        let text = rex_lua(&Layout::default(), Path::new("/fixture/bin/milo"), environment());
        assert!(
            text.contains(&format!(
                "env = {{ XDG_CONFIG_HOME = \"{CONFIG_HOME}\", XDG_STATE_HOME = \"{STATE_HOME}\" }}"
            ))
        );
        assert!(owns_actions(&text));
        assert!(listener_state_matches(&text, Path::new(STATE_HOME)));
        let edited = text.replace('\n', "\r\n") + "\r\n-- keep my comments\r\n";
        assert!(!listener_state_matches(&edited, Path::new("/other/state")));
        let old = strip_scoped_footer(&text, "\n").unwrap().to_owned() + OLD_START_LISTENER;
        assert!(owns_actions(&old));
        let same_layout = Layout::default();
        let executable = Path::new("/fixture/bin/milo");
        let customized = |lua: &str| lua.replace("-- Terminal rows", "-- My custom comment.\n-- Terminal rows");
        assert_eq!(update_actions(&old, &same_layout, executable, environment()), Some(Some(text.clone())));
        assert_eq!(
            update_actions(&customized(&old), &same_layout, executable, environment()),
            Some(Some(customized(&text))),
        );
    }

    #[test]
    #[ignore = "requires Lua 5.1; run by the Rex fixtures CI job"]
    fn rex_lua_fixtures() {
        let f = crate::fixture::Fixture::folder();
        let executable = Path::new("/fixture/bin/milo");
        let actions = f.root.join("enabled.lua");
        let disabled = f.root.join("disabled.lua");
        let listener = f.root.join("listener.lua");
        let layout = Layout::default();
        std::fs::write(&disabled, rex_lua(&layout, executable, environment())).unwrap();
        std::fs::write(&actions, rex_lua(&Layout { new_tabs: true, ..layout }, executable, environment())).unwrap();
        std::fs::write(&listener, listener_lua(&actions)).unwrap();
        let lua = std::env::var_os("LUA51").unwrap_or_else(|| "lua5.1".into());
        let check_environment = format!(
            "local started = false
             rex = {{ action = function() end, exec = {{ start = function(argv, opts)
               assert(argv[1] == '/fixture/bin/milo' and argv[2] == 'listen' and opts.detach)
               assert(opts.env.XDG_CONFIG_HOME == {} and opts.env.XDG_STATE_HOME == {})
               started = true
             end }} }}
             dofile({})
             assert(started)",
            lua_path(Path::new(CONFIG_HOME)),
            lua_path(Path::new(STATE_HOME)),
            lua_path(&actions),
        );
        assert!(
            std::process::Command::new(&lua)
                .env_remove("MILO_CHECKING_REX")
                .args(["-e", &check_environment])
                .status()
                .expect("install Lua 5.1 or set LUA51 to its executable")
                .success()
        );
        let run = |script: &str, files: &[&Path]| {
            let status = std::process::Command::new(&lua)
                .current_dir(concat!(env!("CARGO_MANIFEST_DIR"), "/src/setup"))
                .env_remove("MILO_CHECKING_REX")
                .arg(script)
                .args(files)
                .status()
                .expect("install Lua 5.1 or set LUA51 to its executable");
            assert!(status.success(), "{script}: {status}");
        };
        run("actions_test.lua", &[Path::new("actions.lua")]);
        run("listener_test.lua", &[&listener, &disabled]);
        run("../rex_reader_test.lua", &[Path::new("../rex_reader.lua")]);
    }

    #[test]
    fn explicit_ten_row_settings_are_not_legacy_defaults() {
        let layout = Layout { usage_rows: "10".into(), ..Layout::default() };
        let current = rex_lua(&layout, Path::new("/milo"), environment());
        assert_eq!(Layout::parse(&current).unwrap().usage_rows, "10");
        let customized = current.replace("local usage_rows = 10", "local usage_rows = 10 -- Keep this height");
        assert_eq!(Layout::parse(&customized).unwrap().usage_rows, "10");
        assert_eq!(Layout::parse_rail(&layout.rail_code()).unwrap().usage_rows, "10");
    }
}
